// PARSE REQUEST: Extract decisionId and text from incoming request
// App sends: { decisionId: "dec_u1_001", text: "Can I catch the earlier train?" }

const body = $input.first().json.body || $input.first().json;

const decisionId = body.decisionId;
const userText = body.text;

if (!decisionId) {
  throw new Error('Missing decisionId in request');
}

if (!userText) {
  throw new Error('Missing text in request');
}

return {
  decisionId,
  userText,
  receivedAt: new Date().toISOString()
};

