// BUILD REPLY PROMPT: Combine user text with stored context for Gemini

const requestData = $('Parse Request').first().json;
const decisionRecord = $('Mock Decision Data').first().json;
const contextRecord = $('Mock Context Snapshot').first().json;

const userText = requestData.userText;

// Parse stored JSON fields
const transport = JSON.parse(contextRecord.transport);
const weather = JSON.parse(contextRecord.weather);
const calendar = JSON.parse(contextRecord.calendar);
const originalDecision = {
  decision: decisionRecord.decision,
  recommendation: JSON.parse(decisionRecord.recommendation),
  explanationLong: decisionRecord.explanation_long
};

const systemPrompt = `You are a helpful commute assistant for a user traveling from Hamburg to Bremen via RE4 train.

You have access to the STORED CONTEXT from when the recommendation was made:

TRANSPORT DATA:
${JSON.stringify(transport, null, 2)}

WEATHER DATA:
${JSON.stringify(weather, null, 2)}

CALENDAR DATA:
${JSON.stringify(calendar, null, 2)}

ORIGINAL RECOMMENDATION:
- Decision: ${originalDecision.decision}
- Recommended departure: ${originalDecision.recommendation.recommendedDepartureTime}
- Reason: ${originalDecision.recommendation.reasonLong}

INSTRUCTIONS:
1. Answer the user's question using the stored context data
2. Be conversational but concise - aim for 2-3 sentences
3. Always reference specific data (times, delays, weather conditions)
4. The user has TWO meetings today: Daily Sync at 08:00 (online, can join from home) and Client Presentation at 10:30 (on-site in Bremen, cannot be remote)
5. The 10:30 on-site Client Presentation is the hard constraint - the user MUST be in Bremen for it
6. If the user asks about staying home longer or taking a later train, explain that the Daily Sync is online (fine from home) but the Client Presentation is on-site - the 09:15 arrives at 10:26 (only 4 min before, too risky) and the 10:15 arrives at 11:26 (too late)
7. Recommend the 08:15 connection as the safe choice (arrives 09:26, well before 10:30)
8. Freezing rain and black ice make waiting at the station or driving unsafe
9. Speak in a friendly, reassuring tone
10. Reply with plain text only - no JSON, no markdown, no formatting`;

const userPrompt = `User question: "${userText}"

Provide a helpful response based on the stored context. Consider the train statuses, the freezing rain conditions, and the two meetings (08:00 online Daily Sync, 10:30 on-site Client Presentation).`;

return {
  systemPrompt,
  userPrompt,
  userText,
  decisionId: requestData.decisionId,
  sessionToken: decisionRecord.session_token
};

// Robust Gemini text extraction for n8n
const gemini = $input.first().json;
const prev = $('Build Reply Prompt').first().json;

function get(obj, path) {
  return path.split('.').reduce((o, k) => (o && o[k] !== undefined ? o[k] : undefined), obj);
}

let responseText =
  gemini?.text ??
  gemini?.responseText ??
  gemini?.response ??
  gemini?.output_text ??
  get(gemini, 'data.text') ??
  get(gemini, 'result.text') ??
  get(gemini, 'candidates.0.content.parts.0.text');

// If parts are multiple, join them
if (!responseText && gemini?.candidates?.[0]?.content?.parts?.length) {
  responseText = gemini.candidates[0].content.parts
    .map(p => p?.text)
    .filter(Boolean)
    .join('\n');
}

// Last resort: deep search for the first long-ish string
if (!responseText) {
  const seen = new Set();
  const stack = [gemini];

  while (stack.length) {
    const cur = stack.pop();
    if (!cur || typeof cur !== 'object') continue;
    if (seen.has(cur)) continue;
    seen.add(cur);

    for (const v of Object.values(cur)) {
      if (typeof v === 'string' && v.trim().length > 40) {
        responseText = v.trim();
        stack.length = 0;
        break;
      }
      if (v && typeof v === 'object') stack.push(v);
    }
  }
}

responseText = (responseText || '').trim();

return [
  {
    json: {
      responseText,
      decisionId: prev.decisionId,
      sessionToken: prev.sessionToken,
      // helpful debug fields:
      _debugGeminiKeys: Object.keys(gemini),
      _debugHasCandidates: !!gemini?.candidates?.length
    }
  }
];

// BUILD RESPONSE: Format final response for the mobile app
// App expects: { id, role, text, created_at }

const replyData = $input.first().json;

const response = {
  id: replyData.decisionId,
  role: 'assistant',
  text: replyData.responseText,
  created_at: new Date().toISOString()
};

return response;
